<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api/http'
const tab=ref('monitor'),users=ref<any[]>([]),directions=ref<any[]>([]),knowledge=ref<any[]>([]),audits=ref<any[]>([]),metrics=ref<any>({}),jobs=ref<any>({}),models=ref<any[]>([]),prompts=ref<any[]>([]),dirDialog=ref(false),dir=reactive({code:'',name:'',status:'ACTIVE',sortNo:100})
async function load(){const calls=await Promise.all([api<any>({url:'/admin/users',params:{pageSize:100}}),api<any[]>({url:'/admin/learning-directions'}),api<any[]>({url:'/admin/knowledge-points'}),api<any>({url:'/admin/audit-logs',params:{pageSize:100}}),api<any>({url:'/admin/system-metrics'}),api<any>({url:'/admin/jobs'}),api<any[]>({url:'/admin/model-configs'}),api<any[]>({url:'/admin/prompt-templates'})]);users.value=calls[0].items;directions.value=calls[1];knowledge.value=calls[2];audits.value=calls[3].items;metrics.value=calls[4];jobs.value=calls[5];models.value=calls[6];prompts.value=calls[7]}
onMounted(load)
async function status(u:any){const target=u.status==='ACTIVE'?'DISABLED':'ACTIVE';const reason=await ElMessageBox.prompt(`将用户状态改为 ${target}，请填写原因`,'用户状态变更',{inputValidator:v=>!!v||'原因不能为空'}).then(x=>x.value).catch(()=>null);if(!reason)return;await api({method:'POST',url:`/admin/users/${u.publicId}/status`,data:{status:target,version:u.version,reason}});ElMessage.success('用户状态已更新');await load()}
async function saveDir(){await api({method:'POST',url:'/admin/learning-directions',data:dir});dirDialog.value=false;await load()}
</script>
<template><div><div class="page-head"><div><h2>系统治理与可观测性</h2><p>用户状态、模型、提示词、题库与目录变更均写入审计日志。</p></div></div><section class="panel"><el-tabs v-model="tab"><el-tab-pane label="运行监控" name="monitor"><div class="grid grid-4 admin-stats"><div class="stat"><span class="label">用户总数</span><div class="value">{{metrics.userCount??users.length}}</div></div><div class="stat"><span class="label">运行中作业</span><div class="value">{{jobs.running??0}}</div></div><div class="stat"><span class="label">失败作业</span><div class="value">{{jobs.failed??0}}</div></div><div class="stat"><span class="label">模型配置</span><div class="value">{{models.length}}</div></div></div><el-descriptions title="系统指标" :column="2" border><el-descriptions-item v-for="(v,k) in metrics" :key="k" :label="String(k)">{{v}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane label="用户" name="users"><el-table :data="users"><el-table-column prop="username" label="用户名"/><el-table-column prop="email" label="邮箱"/><el-table-column prop="timezone" label="时区"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link :type="row.status==='ACTIVE'?'danger':'success'" @click="status(row)">{{row.status==='ACTIVE'?'禁用':'启用'}}</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="方向与知识点" name="catalog"><div class="panel-title"><div><h3>学习方向</h3></div><el-button @click="dirDialog=true">新增方向</el-button></div><el-table :data="directions"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="名称"/><el-table-column prop="status" label="状态"/><el-table-column prop="sortNo" label="排序"/></el-table><el-divider/><h3>知识点（{{knowledge.length}}）</h3><el-table :data="knowledge" max-height="360"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="名称"/><el-table-column prop="level" label="层级"/><el-table-column prop="status" label="状态"/></el-table></el-tab-pane><el-tab-pane label="模型与提示词" name="ai"><h3>模型配置</h3><el-table :data="models"><el-table-column prop="providerName" label="服务商"/><el-table-column prop="purpose" label="用途"/><el-table-column prop="modelName" label="模型"/><el-table-column prop="status" label="状态"/></el-table><el-divider/><h3>提示词模板</h3><el-table :data="prompts"><el-table-column prop="code" label="编码"/><el-table-column prop="versionNo" label="版本"/><el-table-column prop="status" label="状态"/></el-table></el-tab-pane><el-tab-pane label="审计日志" name="audit"><el-table :data="audits"><el-table-column prop="createdAt" label="时间" width="190"/><el-table-column prop="action" label="操作"/><el-table-column prop="resourceType" label="资源"/><el-table-column prop="resourceId" label="公开标识"/><el-table-column prop="result" label="结果"/></el-table></el-tab-pane></el-tabs></section><el-dialog v-model="dirDialog" title="新增学习方向" width="460"><el-form label-position="top"><el-form-item label="编码"><el-input v-model="dir.code"/></el-form-item><el-form-item label="名称"><el-input v-model="dir.name"/></el-form-item><el-form-item label="排序"><el-input-number v-model="dir.sortNo"/></el-form-item></el-form><template #footer><el-button @click="dirDialog=false">取消</el-button><el-button type="primary" @click="saveDir">保存</el-button></template></el-dialog></div></template>
<style scoped>.admin-stats{background:#eef3ee;border-radius:12px;margin-bottom:20px}.admin-stats .stat{border-right:1px solid #d6ded7}.admin-stats .value{font-size:30px}</style>
